<script setup lang="ts">
import { computed } from 'vue'
import { useChronos } from '@/composables/useChronos'
import { useCalendar, format } from '@/composables/useCalendar'
const {selected,selectedDaily,valueField,filters,seriesLabel}=useChronos();const {monthName}=useCalendar()
const max=computed(()=>Math.max(1,...selectedDaily.value.map(d=>d[valueField.value]??0)))
const bars=computed(()=>selectedDaily.value.map(d=>({date:d.date_utc,value:d[valueField.value],height:(d[valueField.value]??0)/max.value*100})))
const maxComparison=computed(()=>Math.max(1,selected.value?.paired_modis??0,selected.value?.paired_viirs??0,selected.value?.paired_calibrated??0))
</script>
<template>
<section class="panel" aria-labelledby="daily-title"><header class="daily-head"><div><span class="section-kicker">ACERCARSE AL DETALLE</span><h2 class="panel-title" id="daily-title">{{selected?`${monthName(selected.month)} ${selected.year}`:'Detalle diario'}}</h2></div><span class="small-note">{{seriesLabel}} · celdas / día</span></header>
<div class="daily-chart" role="img" :aria-label="`Actividad diaria de ${selected?monthName(selected.month):'mes seleccionado'}`"><div class="day-column" v-for="bar in bars" :key="bar.date"><div class="bar-space"><span class="daily-bar" :class="{'missing-bar':bar.value===null}" :style="{height:bar.value===null?'100%':`${Math.max(bar.height,bar.value===0?1:2)}%`}" :title="`${bar.date}: ${bar.value===null?'sin dato':format(bar.value)+' celdas'}`"></span></div><span class="day-label">{{Number(bar.date.slice(-2))%5===0||bar.date.endsWith('01')?Number(bar.date.slice(-2)):''}}</span></div></div>
<template v-if="!filters.bbox&&selected&&selected.paired_days>0"><h3 class="comparison-title">Observado y calibrado · los mismos {{selected.paired_days}} días elegibles</h3><div class="compare-bars"><div v-for="item in [{name:'MODIS observado',value:selected.paired_modis},{name:'VIIRS observado',value:selected.paired_viirs},{name:'VIIRS → escala MODIS',value:selected.paired_calibrated}]" :key="item.name"><span>{{item.name}}</span><div class="compare-track"><i :style="{width:`${item.value/maxComparison*100}%`}"></i></div><strong>{{format(item.value)}}</strong></div></div><p class="small-note">Sumas de celda-días en fechas comparables; pueden ser parciales. La estimación calibrada no se suma a MODIS.</p></template>
<details><summary>Ver valores diarios accesibles</summary><div class="daily-table-wrap"><table class="daily-table"><thead><tr><th>Fecha UTC</th><th>MODIS</th><th>VIIRS</th><th v-if="!filters.bbox">VIIRS calibrado</th><th v-if="!filters.bbox">Intervalo empírico</th></tr></thead><tbody><tr v-for="d in selectedDaily" :key="d.date_utc"><th scope="row">{{d.date_utc}}</th><td>{{format(d.active_cells_modis)}}</td><td>{{d.active_cells_viirs===null?'—':format(d.active_cells_viirs)}}</td><td v-if="!filters.bbox">{{d.modis_equivalent_cells===null?'—':format(d.modis_equivalent_cells)}}</td><td v-if="!filters.bbox">{{d.modis_pi90_low===null||d.modis_pi90_high===null?'—':`${format(d.modis_pi90_low)}–${format(d.modis_pi90_high)}`}}</td></tr></tbody></table></div></details>
</section>
</template>
<style scoped>
.daily-head{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;align-items:center}.daily-chart{display:flex;gap:4px;height:170px;margin:24px 0}.day-column{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}.bar-space{height:145px;display:flex;align-items:end;border-bottom:1px solid #2E96F5}.daily-bar{width:100%;display:block;background:#2E96F5;border-radius:3px 3px 0 0}.missing-bar{background:repeating-linear-gradient(135deg,#0042A6,#0042A6 3px,transparent 3px,transparent 6px);opacity:.7}.day-label{height:15px;text-align:center;font-size:10px}.comparison-title{font:700 15px var(--font-body);text-transform:none;letter-spacing:0}.compare-bars{margin:16px 0;display:flex;flex-direction:column;gap:12px}.compare-bars>div{display:grid;grid-template-columns:165px 1fr 90px;align-items:center;gap:12px;font-size:13px}.compare-bars strong{text-align:right}.compare-track{height:9px;background:#0042A6;border-radius:5px;overflow:hidden}.compare-track i{height:100%;display:block;background:#2E96F5}.compare-bars>div:last-child i{background:white}summary{cursor:pointer;font-weight:700;padding:12px 0;font-size:14px}.daily-table-wrap{max-height:300px;overflow:auto}.daily-table{border-collapse:collapse;width:100%;font-size:12px}.daily-table td,.daily-table th{padding:8px;text-align:right;border-bottom:1px solid #0042A6}.daily-table th:first-child{text-align:left;white-space:nowrap}@media(max-width:600px){.compare-bars>div{grid-template-columns:135px 1fr 65px;font-size:11px;gap:5px}.daily-chart{gap:2px}}
</style>
